import { DestroyRef, DOCUMENT, Injectable, computed, effect, inject, signal } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { NavigationEnd, Router } from '@angular/router';
import { filter, map } from 'rxjs';

export type Theme = 'light' | 'dark';

export interface Destination {
  readonly path: string;
  readonly label: string;
  readonly icon: string;
}

export interface Crumb {
  readonly label: string;
  readonly path: string;
}

const THEME_KEY = 'hero-ops-theme';

export const DESTINATIONS: readonly Destination[] = [
  { path: '/dashboard', label: 'Dashboard', icon: 'lucideLayoutDashboard' },
  { path: '/roster', label: 'Roster', icon: 'lucideUsers' },
  { path: '/threats', label: 'Threats', icon: 'lucideShieldAlert' },
  { path: '/recruit', label: 'Recruit', icon: 'lucideUserPlus' },
  { path: '/settings', label: 'Settings', icon: 'lucideSettings' },
];

// Owns the shell's state: the theme, and the breadcrumb derived from the route.
// Component-scoped (provided by App), so it has no providedIn.
@Injectable()
export class AppViewModel {
  private readonly router = inject(Router);
  private readonly destroyRef = inject(DestroyRef);
  private readonly document = inject(DOCUMENT);
  private readonly window = this.document.defaultView;
  private readonly systemDark = this.window?.matchMedia?.('(prefers-color-scheme: dark)') ?? null;

  readonly destinations = DESTINATIONS;

  // A stored choice wins. With no choice, follow the operating system.
  private readonly theme = signal<Theme>(
    this.storedTheme() ?? (this.systemDark?.matches ? 'dark' : 'light'),
  );
  readonly isDark = computed(() => this.theme() === 'dark');
  readonly nextThemeLabel = computed(() =>
    this.isDark() ? 'Switch to light theme' : 'Switch to dark theme',
  );

  private readonly url = toSignal(
    this.router.events.pipe(
      filter((event): event is NavigationEnd => event instanceof NavigationEnd),
      map((event) => event.urlAfterRedirects),
    ),
    { initialValue: this.router.url },
  );

  readonly crumbs = computed<readonly Crumb[]>(() => {
    const [section, id] = this.url().split(/[?#]/)[0].split('/').filter(Boolean);
    const crumbs: Crumb[] = [{ label: 'Hero Ops', path: '/dashboard' }];
    if (section === 'detail') {
      crumbs.push(
        { label: 'Roster', path: '/roster' },
        { label: id ? `Hero ${id}` : 'Hero', path: this.url() },
      );
    } else {
      const destination = DESTINATIONS.find((d) => d.path === `/${section}`);
      if (destination) crumbs.push({ label: destination.label, path: destination.path });
    }
    return crumbs;
  });

  constructor() {
    effect(() => {
      this.document.documentElement.classList.toggle('dark', this.isDark());
    });

    const onSystemChange = (event: MediaQueryListEvent) => {
      if (this.storedTheme() === null) this.theme.set(event.matches ? 'dark' : 'light');
    };
    this.systemDark?.addEventListener('change', onSystemChange);
    this.destroyRef.onDestroy(() => this.systemDark?.removeEventListener('change', onSystemChange));
  }

  toggleTheme(): void {
    const next: Theme = this.isDark() ? 'light' : 'dark';
    this.theme.set(next);
    this.window?.localStorage.setItem(THEME_KEY, next);
  }

  private storedTheme(): Theme | null {
    const value = this.window?.localStorage.getItem(THEME_KEY);
    return value === 'light' || value === 'dark' ? value : null;
  }
}
/** Power classes a hero can be filed under. Drives the roster class filter and badges. */
export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

/** Roster status. `Active` is the only status a hero can be deployed from. */
export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

/** Clearance tier, 1 (lowest) to 5 (highest). Stored as a number so it sorts; shown as "Tier N". */
export const CLEARANCE_TIERS = [1, 2, 3, 4, 5] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index, 0-100. */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearance: ClearanceTier;
  readonly missions: number;
  /** Mission success rate as a percentage, 0-100. */
  readonly successRate: number;
  /** Dossier notes shown on the detail screen and edited in its form. */
  readonly notes: string;
}
import { Service, computed, signal } from '@angular/core';
import { EXAMPLE_ROSTER } from './hero.example-data';
import type { Hero } from './hero.model';

/**
 * In-memory hero store. Holds EXAMPLE DATA (see `hero.example-data.ts`) as signal
 * state; there is no backend, so updates last only until the page reloads.
 */
@Service()
export class HeroService {
  private readonly heroes = signal<readonly Hero[]>(EXAMPLE_ROSTER);

  /** The full roster, read-only. */
  readonly list = this.heroes.asReadonly();
  readonly count = computed(() => this.heroes().length);

  /** Looks up a hero by id. Reads the signal, so calling it inside a `computed` stays reactive. */
  byId(id: string): Hero | undefined {
    return this.heroes().find((hero) => hero.id === id);
  }

  /**
   * Applies a partial update to the hero with `id` and returns the stored record,
   * or `undefined` if no hero has that id. The id itself cannot be changed.
   */
  update(id: string, patch: Partial<Omit<Hero, 'id'>>): Hero | undefined {
    const current = this.byId(id);
    if (!current) {
      return undefined;
    }
    const next: Hero = { ...current, ...patch };
    this.heroes.update((list) => list.map((hero) => (hero.id === id ? next : hero)));
    return next;
  }
}
