import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideRouter } from '@angular/router';
import { routes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideRouter(routes)
  ]
};
<div hlmSidebarWrapper>
  <hlm-sidebar>
    <div hlmSidebarHeader>
      <p class="px-2 py-1 text-base font-semibold">Hero Ops Console</p>
    </div>

    <div hlmSidebarContent>
      <div hlmSidebarGroup>
        <div hlmSidebarGroupLabel>Operations</div>
        <div hlmSidebarGroupContent>
          <ul hlmSidebarMenu>
            @for (destination of vm.destinations; track destination.path) {
              <li hlmSidebarMenuItem>
                <a
                  hlmSidebarMenuButton
                  [routerLink]="destination.path"
                  routerLinkActive
                  #active="routerLinkActive"
                  [isActive]="active.isActive"
                >
                  <ng-icon [name]="destination.icon" />
                  <span>{{ destination.label }}</span>
                </a>
              </li>
            }
          </ul>
        </div>
      </div>
    </div>

    <div hlmSidebarFooter>
      <p class="px-2 text-xs text-sidebar-foreground">Ops Director</p>
    </div>
  </hlm-sidebar>

  <main hlmSidebarInset class="min-w-0">
    <header class="flex flex-wrap items-center gap-2 border-b border-border px-4 py-3 md:px-6">
      <button hlmSidebarTrigger></button>

      <nav aria-label="Breadcrumb" class="min-w-0 flex-1">
        <ol class="flex min-w-0 items-center gap-1 text-sm">
          @for (crumb of vm.crumbs(); track $index; let last = $last) {
            <li class="flex min-w-0 items-center gap-1">
              @if (last) {
                <span class="truncate font-medium" aria-current="page">{{ crumb.label }}</span>
              } @else {
                <a class="truncate text-muted-foreground hover:text-foreground" [routerLink]="crumb.path">{{ crumb.label }}</a>
                <span class="text-muted-foreground" aria-hidden="true">/</span>
              }
            </li>
          }
        </ol>
      </nav>

      <div class="order-last flex w-full min-w-0 items-center gap-2 sm:order-none sm:w-64">
        <ng-icon name="lucideSearch" class="shrink-0 text-muted-foreground" />
        <input
          hlmInput
          type="search"
          placeholder="Search heroes and missions"
          aria-label="Search heroes and missions"
        />
      </div>

      <button hlmBtn variant="ghost" size="icon" hlmTooltip="Notifications" aria-label="Notifications">
        <ng-icon name="lucideBell" />
      </button>

      <button
        hlmBtn
        variant="ghost"
        size="icon"
        [hlmTooltip]="vm.nextThemeLabel()"
        [attr.aria-label]="vm.nextThemeLabel()"
        (click)="vm.toggleTheme()"
      >
        @if (vm.isDark()) {
          <ng-icon name="lucideSun" />
        } @else {
          <ng-icon name="lucideMoon" />
        }
      </button>

      <hlm-avatar size="sm" role="img" aria-label="Operator account">
        <span hlmAvatarFallback>OP</span>
      </hlm-avatar>
    </header>

    <div class="min-w-0 flex-1 p-4 md:p-6">
      <router-outlet />
    </div>
  </main>
</div>
