  constructor() {
    effect(() => {
      this.document.documentElement.classList.toggle('dark', this.isDark());
    });

    const onSystemChange = (event: MediaQueryListEvent) => {
      if (this.storedTheme() === null) this.theme.set(event.matches ? 'dark' : 'light');
    };
    this.systemDark?.addEventListener('change', onSystemChange);
    this.destroyRef.onDestroy(() => this.systemDark?.removeEventListener('change', onSystemChange));
  }

  toggleTheme(): void {
    const next: Theme = this.isDark() ? 'light' : 'dark';
    this.theme.set(next);
    this.window?.localStorage.setItem(THEME_KEY, next);
  }

  private storedTheme(): Theme | null {
    const value = this.window?.localStorage.getItem(THEME_KEY);
    return value === 'light' || value === 'dark' ? value : null;
  }
